import fs from "node:fs/promises";
import { createHash } from "node:crypto";
import assert from "node:assert/strict";
import { createClient } from "@supabase/supabase-js";
import { variantTag, variantsFromTags } from "../lib/product-utils.ts";

// Input is generated by visually checking the quotation and matching its image cells.
const manifestPath = process.argv[2] || "tmp/pdfs/import-manifest.json";
const products = JSON.parse(await fs.readFile(manifestPath, "utf8"));
assert.equal(products.length, 57);
assert.equal(products.reduce((sum, product) => sum + product.variants.length, 0), 384);
const supabase = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SECRET_KEY || process.env.SUPABASE_SERVICE_ROLE_KEY, { auth: { persistSession: false, autoRefreshToken: false } });
const { data: existing, error: readError } = await supabase.from("products").select("*").in("sku", products.map(product => product.sku));
if (readError) throw readError;
const backupPath = `tmp/pdfs/products-before-import-${Date.now()}.json`;
await fs.writeFile(backupPath, JSON.stringify(existing, null, 2));
console.log(`Backed up ${existing.length} matching products to ${backupPath}.`);
if (!process.argv.includes("--apply") && !process.argv.includes("--verify-only")) {
  console.log("Dry run complete. Add --apply to upload images and save products.");
  process.exit(0);
}
const bucket = "product-images";
if (!(await supabase.storage.getBucket(bucket)).data) throw new Error("Product image bucket is not configured.");
const oldBySku = new Map(existing.map(row => [row.sku, row]));
const verifyOnly = process.argv.includes("--verify-only");
const rows = verifyOnly ? JSON.parse(await fs.readFile("tmp/pdfs/imported-product-rows.json", "utf8")) : [];
for (const product of verifyOnly ? [] : products) {
  const variants = [];
  for (const source of product.variants) {
    const bytes = await fs.readFile(source.sourceImage.file);
    const hash = createHash("sha256").update(bytes).digest("hex").slice(0, 16);
    const path = `quotation-2610/${product.sku}/${source.sku}-${hash}.png`;
    const { error } = await supabase.storage.from(bucket).upload(path, bytes, { contentType: "image/png", upsert: false });
    if (error && String(error.statusCode) !== "409") throw new Error(`Image ${source.sku}: ${error.message}`);
    const variant = { ...source };
    delete variant.sourceImage;
    variants.push({ ...variant, imageUrl: supabase.storage.from(bucket).getPublicUrl(path).data.publicUrl });
  }
  const old = oldBySku.get(product.sku);
  const tiers = product.priceTiers.map(t => `price-tier:${t.minimumQuantity}:${Number(t.price.slice(1))}`);
  const retainedTags = (old?.tags || []).filter(tag => !tag.startsWith("price-tier:") && !tag.startsWith("variant-json:"));
  const ranges = product.material.startsWith("PLA") || product.material.startsWith("PETG") ? ["1-100", "100-500", "500-1000"] : ["1-20", "20-200", "200-500"];
  const row = {
    sku: product.sku, name: product.name, material: product.material,
    color: product.colors.join(", "), image_url: variants[0].imageUrl,
    price: Number(product.price.slice(1)), currency: "USD", moq: product.moq,
    ...(product.weight !== "Not specified" ? { weight: product.weight } : {}),
    stock_status: "Quote available", lead_time: "Confirm before order", active: true,
    sheet_updated_at: new Date().toISOString(),
    tags: [...new Set([...retainedTags, "b2b", "quotation-2610", ...tiers, variantTag(variants)])],
    description: `Source: Product quotation-2610.pdf, page ${product.sourcePages.join(", ")}. Supplier: XinRui Manufacturing Technology LTD. Phone/WhatsApp: +86 19120836592. Website: www.filazoo.com. Alibaba: filazoo.en.alibaba.com. EXW USD unit prices: ${product.priceTiers.map((t, i) => `${ranges[i]} pcs ${t.price}`).join("; ")}. Colors: ${product.colors.join(", ")}. ${product.sourceNote || ""} Internal CRM SKUs identify product/color combinations; the quotation does not supply SKUs.`,
  };
  rows.push(row);
  console.log(`Prepared ${product.sku}: ${variants.length} images.`);
}
if (!verifyOnly) {
  await fs.writeFile("tmp/pdfs/imported-product-rows.json", JSON.stringify(rows, null, 2));
  const { error: writeError } = await supabase.from("products").upsert(rows, { onConflict: "sku" });
  if (writeError) throw writeError;
}
const { data: saved, error: verifyError } = await supabase.from("products").select("*").in("sku", rows.map(row => row.sku));
if (verifyError) throw verifyError;
assert.equal(saved.length, rows.length);
for (const expected of rows) {
  const actual = saved.find(row => row.sku === expected.sku);
  for (const key of Object.keys(expected)) {
    if (key === "sheet_updated_at") assert.equal(Date.parse(actual[key]), Date.parse(expected[key]));
    else assert.deepEqual(actual[key], expected[key], `${expected.sku}.${key}`);
  }
  const variants = variantsFromTags(actual.tags, [], actual.sku, "", "");
  assert.equal(variants.length, products.find(p => p.sku === actual.sku).variants.length);
  const fromIndex = process.argv.indexOf("--verify-from");
  const firstSku = fromIndex >= 0 ? process.argv[fromIndex + 1] : null;
  if (firstSku && rows.indexOf(expected) < rows.findIndex(row => row.sku === firstSku)) continue;
  for (let start = 0; start < variants.length; start += 8) {
    await Promise.all(variants.slice(start, start + 8).map(async variant => {
      for (let attempt = 0; ; attempt++) {
        try {
          const response = await fetch(variant.imageUrl, { method: "HEAD", signal: AbortSignal.timeout(15000) });
          assert.equal(response.status, 200, `${variant.sku} image not accessible`);
          break;
        } catch (error) { if (attempt >= 2) throw error; }
      }
    }));
  }
  console.log(`Verified ${actual.sku}: details and ${variants.length} images.`);
}
console.log(`Imported and read-back verified ${saved.length} products, 384 variants/images, and 171 product price tiers. All 384 image URLs returned HTTP 200.`);
